<section class="lm-page-hero lm2-list-hero"><div class="lm-container"><span class="lm2-eyebrow">Explore our catalogue</span><h1 class="lm-page-title">Learn something new today.</h1><p class="lm-page-subtitle">Discover practical skills and find a course that fits where you want to go.</p><form class="lm2-filter-bar" action="/courses" method="get" role="search"><label for="catalog-q" class="visually-hidden">Search courses</label><input id="catalog-q" name="q" type="search" value="<?= e($search) ?>" maxlength="150" placeholder="Search by course name or topic..."><label for="catalog-category" class="visually-hidden">Course category</label><select id="catalog-category" name="category"><option value="">All categories</option><?php foreach ($categories as $cat): ?><option value="<?= e($cat['slug']) ?>" <?= $category === $cat['slug']?'selected':'' ?>><?= e($cat['name']) ?></option><?php endforeach; ?></select><button class="lm-button lm-button-primary" type="submit">Find courses ↗</button></form></div></section>
<section class="lm-section lm-section-soft"><div class="lm-container"><div class="lm2-section-heading"><div><span class="lm2-eyebrow">The collection</span><h2><?= $search !== '' ? 'Your search results' : ($category !== '' ? 'Courses in this category' : 'Explore all courses') ?></h2><p><?= (int)$total ?> <?= (int)$total === 1 ? 'course' : 'courses' ?> available</p></div><?php if ($search !== '' || $category !== ''): ?><a href="/courses" class="lm-button lm-button-outline">Clear filters</a><?php endif; ?></div>
<?php if (!empty($previewMode)): ?><div class="lm3-preview-notice"><span class="lm3-demo-chip">Demo content</span><div><strong>10 sample courses for visual review</strong><p>These are examples only, not published lessons. All details and images are temporary previews; enrollment is disabled.</p></div></div><?php endif; ?><?php if (!$courses): ?><div class="lm2-empty"><div class="lm2-empty-illustration">⌕</div><h3><?= $search!==''||$category!==''?'No courses match these filters.':'Your next course is coming soon.' ?></h3><p><?= $search!==''||$category!==''?'Try another topic, keyword or category.':'Published courses will appear here as soon as they are available.' ?></p><a href="/courses" class="lm-button lm-button-primary">Explore all courses</a></div>
<?php else: ?><div class="lm2-course-grid"><?php foreach ($courses as $course): ?><article class="lm2-course-card"><div class="lm2-course-art"><img class="lm3-cover" loading="lazy" decoding="async" width="640" height="360" src="/learmingo-course-cover?slug=<?= rawurlencode((string)$course['slug']) ?>" alt="<?= e($course['category_name'] ?? 'Course') ?> course cover" /><span class="lm2-course-badge"><?= !empty($course['is_preview']) ? 'Demo · ' : '' ?><?= e($course['category_name'] ?: 'Course') ?></span></div><div class="lm2-course-body"><span class="lm2-course-overline"><?= !empty($course['is_preview']) ? 'SAMPLE COURSE PREVIEW' : 'SELF-PACED LEARNING' ?></span><h3><a href="/course?slug=<?= rawurlencode((string)$course['slug']) ?>"><?= e($course['title']) ?></a></h3><p>By <?= e($course['instructor']) ?></p><p class="lm2-course-desc"><?= e(substr((string)$course['description'],0,145)) ?></p><?php if (!empty($course['is_preview'])): ?><div class="lm3-course-metadata"><span><?= e($course['lessons']) ?></span><span><?= e($course['duration']) ?></span><span><?= e($course['level']) ?></span></div><?php endif; ?><div class="lm2-course-bottom"><strong><?= (float)$course['price']<=0?'Free':'$'.e(number_format((float)$course['price'],2)) ?></strong><a href="/course?slug=<?= rawurlencode((string)$course['slug']) ?>">View course →</a></div></div></article><?php endforeach; ?></div>
<?php if ($pages>1): ?><nav class="lm2-pagination" aria-label="Course catalogue pages"><?php for($n=max(1,$page-2);$n<=min($pages,$page+2);$n++): ?><a href="/courses?<?= e(http_build_query(['q'=>$search,'category'=>$category,'page'=>$n])) ?>" <?= $n===$page?'aria-current="page"':'' ?>><?= $n ?></a><?php endfor; ?></nav><?php endif; ?><?php endif; ?>
</div></section>
